#!/usr/bin/env bash
# S-T shard 1 failed (one stream of 16,400 prompt tokens > 16,384): rerun it with a 32k context on card 2, then the
# S-T post job. Waits for run_speech.sh to finish (holders back), takes card 2 from its holder, returns it at the end.
set -uo pipefail
cd /opt/dlami/nvme/jasonleeeli/projects/UniSS
log() { echo "[$(TZ=Europe/Prague date +%H:%M:%S)] $*"; }
until grep -q SPEECH_FULL_DONE logs/gstar_speech_full_run.log; do sleep 30; done
bash /tmp/claude-0/-opt-dlami-nvme-jasonleeeli-projects-UniSS/88583ca0-585a-4fad-ada7-4b193b743b50/scratchpad/holder_off.sh 2567
sleep 20
log "S-T talk1 (32k)"
CUDA_VISIBLE_DEVICES=2 VLLM_USE_FLASHINFER_SAMPLER=0 VLLM_CACHE_ROOT=/opt/dlami/nvme/jasonleeeli/cache/vllm_omni_030 PYTHONPATH=. OMP_NUM_THREADS=16 /opt/dlami/nvme/jasonleeeli/venvs/vllm_omni_030/bin/python -m experiments.uniss_qwen3_omni_v1.evaluation.si_infer --model eval_outputs/uniss_qwen3_omni_v1/si_t1c_20261021T181440Z/autoext/export_1500/uniss --direction en2zh --window 1 --output eval_outputs/uniss_qwen3_omni_v1/gstar_speech_full_20261028/S-T_d1/talker --text-policy file --blocks-file eval_outputs/uniss_qwen3_omni_v1/gstar_speech_full_20261028/S-T_d1/talker_in/blocks.jsonl --items-file eval_outputs/uniss_qwen3_omni_v1/gstar_speech_full_20261028/S-T_d1/talker_in/items.jsonl --speed-policy fixed --history-ban 8 --max-model-len 32768 --gpu-mem 0.3 --shard 1 --num-shards 8 > logs/gstar_speech_full/S-T_d1_talk1_retry.log 2>&1 || { log "talk1 failed"; bash /tmp/claude-0/-opt-dlami-nvme-jasonleeeli-projects-UniSS/88583ca0-585a-4fad-ada7-4b193b743b50/scratchpad/holder_on.sh 2,5,6,7; exit 1; }
log "S-T post"
bash -c 'set -e; cat eval_outputs/uniss_qwen3_omni_v1/gstar_speech_full_20261028/S-T_d1/talker/part_*.jsonl > eval_outputs/uniss_qwen3_omni_v1/gstar_speech_full_20261028/S-T_d1/talker/results.jsonl; /opt/dlami/nvme/jasonleeeli/conda_envs/uniss-eval/bin/python /tmp/claude-0/-opt-dlami-nvme-jasonleeeli-projects-UniSS/d490b1cc-23c2-464f-a450-9958e1eda107/scratchpad/p80_speechonly.py eval_outputs/uniss_qwen3_omni_v1/gstar_speech_full_20261028/S-T_d1/talker; CUDA_VISIBLE_DEVICES=2 PYTHONPATH=. /opt/dlami/nvme/jasonleeeli/conda_envs/uniss-eval/bin/python -m evaluation.asr_transcribe --input eval_outputs/uniss_qwen3_omni_v1/gstar_speech_full_20261028/S-T_d1/talker/results_speechonly.jsonl --output eval_outputs/uniss_qwen3_omni_v1/gstar_speech_full_20261028/S-T_d1/talker/asr_speech.jsonl --device cuda:0 --batch-size 16 > eval_outputs/uniss_qwen3_omni_v1/gstar_speech_full_20261028/S-T_d1/asr.log 2>&1; PYTHONPATH=. /opt/dlami/nvme/jasonleeeli/conda_envs/uniss-eval/bin/python -m experiments.uniss_qwen3_omni_v1.evaluation.gstar_talker stitch --results eval_outputs/uniss_qwen3_omni_v1/gstar_speech_full_20261028/S-T_d1/talker/results.jsonl --prep eval_outputs/uniss_qwen3_omni_v1/gstar_speech_full_20261028/S-T_d1/talker_in --windows data/ami_multispk_si_v1/e2e_gstar_stream_v1/windows_test_ref.jsonl --mode stream --out eval_outputs/uniss_qwen3_omni_v1/gstar_speech_full_20261028/S-T_d1/stitched; PYTHONPATH=. /opt/dlami/nvme/jasonleeeli/conda_envs/uniss-eval/bin/python -m experiments.uniss_qwen3_omni_v1.evaluation.gstar_score --windows data/ami_multispk_si_v1/e2e_gstar_stream_v1/windows_test_ref.jsonl --hyp eval_outputs/uniss_qwen3_omni_v1/gstar_stream_eval_o1_20261026T195403Z/S-T_d1/hyp.jsonl --asr eval_outputs/uniss_qwen3_omni_v1/gstar_speech_full_20261028/S-T_d1/talker/asr_speech.jsonl --post-key lowlat --out eval_outputs/uniss_qwen3_omni_v1/gstar_speech_full_20261028/S-T_d1/score.json > eval_outputs/uniss_qwen3_omni_v1/gstar_speech_full_20261028/S-T_d1/score.log 2>&1' > logs/gstar_speech_full/S-T_d1_post_retry.log 2>&1 || log "post failed"
sleep 10
bash /tmp/claude-0/-opt-dlami-nvme-jasonleeeli-projects-UniSS/88583ca0-585a-4fad-ada7-4b193b743b50/scratchpad/holder_on.sh 2,5,6,7
log "FIX_DONE"
